import java.io.*;
import java.util.*;

class TreeNode {
    int val; TreeNode left, right;
    TreeNode(int v) { val = v; }
}

public class Main {
    static boolean isNull(String s) {
        return s.equals("null") || s.equals("None") || s.equals("#");
    }

    static TreeNode mk(String s) { return isNull(s) ? null : new TreeNode(Integer.parseInt(s)); }

    static TreeNode build(String[] t, int from) {     // 层序建树，遇 null 跳过
        if (from >= t.length || isNull(t[from])) return null;
        TreeNode root = mk(t[from]);
        Deque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        for (int i = from + 1; i < t.length && !q.isEmpty(); ) {
            TreeNode p = q.poll();
            if ((p.left = mk(t[i])) != null) q.add(p.left);
            i++;
            if (i < t.length && (p.right = mk(t[i])) != null) q.add(p.right);
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        for (String line; (line = br.readLine()) != null; ) sb.append(line).append(' ');
        String[] t = sb.toString().trim().split("\\s+");
        TreeNode root = build(t, 1);                 // 第一行是 n，后面是层序值

        System.out.println(new Solution().maxDepth(root));
    }
}

