        StreamTokenizer in = new StreamTokenizer(br);
        in.nextToken(); int n = (int) in.nval;
        in.nextToken(); int bag = (int) in.nval;
        int[] weight = new int[n], value = new int[n];
        for (int i = 0; i < n; i++) { in.nextToken(); weight[i] = (int) in.nval; }
        for (int i = 0; i < n; i++) { in.nextToken(); value[i] = (int) in.nval; }

        int[] dp = new int[bag + 1];
        for (int i = 0; i < n; i++)
            for (int j = bag; j >= weight[i]; j--)          // 01 背包倒序；完全背包正序
                dp[j] = Math.max(dp[j], dp[j - weight[i]] + value[i]);
        System.out.println(dp[bag]);
    }
}

